Lemma geo_1RB1LA_1LC1RD_1LA1RD_0LA0RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1LC1RD_1LA1RD_0LA0RC) = lift (Cc (Pos.succ p)).
