(** ** The lap *)

Lemma lap_1RB1LA_1LC1RD_1LA1RD_0LA0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LC1RD_1LA1RD_0LA0RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC1RD_1LA1RD_0LA0RC B0_1RB1LA_1LC1RD_1LA1RD_0LA0RC B1_1RB1LA_1LC1RD_1LA1RD_0LA0RC 4 13 p j' [] []).
    + exact run_ovf_1RB1LA_1LC1RD_1LA1RD_0LA0RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LC1RD_1LA1RD_0LA0RC p j' E).
    + exact (geo_1RB1LA_1LC1RD_1LA1RD_0LA0RC p j' E).
    + lia.
Qed.

