(** ** The lap *)

Lemma lap_1RB1LA_1RC0RB_1LC1LD_0LA0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
