  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1RC0RB_1LC1LD_0LA0RC B0_1RB1LA_1RC0RB_1LC1LD_0LA0RC B1_1RB1LA_1RC0RB_1LC1LD_0LA0RC 2 8 p j' [] []).
