Lemma lbl_1RB1LB_1LA0RC_0LC1RD_1LC0RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LB_1LA0RC_0LC1RD_1LC0RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LB_1LA0RC_0LC1RD_1LC0RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LB_1LA0RC_0LC1RD_1LC0RD
             = (StC, (rep [S0] (S j) ++ [S1], S0, [S1;S0;S1]))).
